// 把多段文本各自按 wrap 折行，段与段之间空一行。
// 按行拼：每个非首段前先补一行空行作分隔，空段自身不产生折行结果
// （于是 ["aa","","bb"] 得到 "aa" + 空行 + 空行 + "bb"）。
export function joinFitted(segments, maxWidth) {
  const lines = [];
  segments.forEach((segment, index) => {
    if (index > 0) lines.push("");
    lines.push(...wrap(segment, maxWidth));
  });
  return lines.join("\n");
}

